<?php
declare(strict_types=1);
/**
 * /webhook/{channel_key} — Meta (WhatsApp, Messenger, Instagram) and Twilio WhatsApp webhooks.
 * Verifies, stores the event durably, answers 200 immediately. Replies are generated by the queue worker.
 */

use CaliChat\Core\Crypto;
use CaliChat\Core\Db;
use CaliChat\Core\Log;
use CaliChat\Services\Meta;
use CaliChat\Services\Queue;
use CaliChat\Services\Twilio;

$key = preg_replace('/[^a-f0-9]/', '', $seg[1] ?? '');
$channel = $key ? Db::one("SELECT * FROM channels WHERE channel_key=?", [$key]) : null;
if (!$channel) { http_response_code(404); exit('unknown channel'); }
$isTwilio = $channel['type'] === 'twilio_whatsapp';

if ($_SERVER['REQUEST_METHOD'] === 'GET') {
    if ($isTwilio) { header('Content-Type: text/plain'); exit('CaliChat Twilio webhook: configure this URL in Twilio with method POST.'); }
    if (($_GET['hub_mode'] ?? $_GET['hub.mode'] ?? '') === 'subscribe' && hash_equals($channel['verify_token'], (string)($_GET['hub_verify_token'] ?? $_GET['hub.verify_token'] ?? ''))) {
        header('Content-Type: text/plain'); echo $_GET['hub_challenge'] ?? $_GET['hub.challenge'] ?? ''; exit; // Meta verification handshake
    }
    http_response_code(403); exit('forbidden');
}

$raw = file_get_contents('php://input') ?: '';
if (strlen($raw) > 1048576) { http_response_code(413); exit('too large'); }

if ($isTwilio) {
    if (!Twilio::verifySignature($channel, $_POST, $_SERVER['HTTP_X_TWILIO_SIGNATURE'] ?? null)) {
        Log::warn('webhook_bad_signature', ['channel' => (int)$channel['id'], 'type' => 'twilio']);
        http_response_code(403); exit('bad signature');
    }
    $events = Twilio::parse($channel, $_POST);
    $ackType = 'text/xml'; $ackBody = '<?xml version="1.0" encoding="UTF-8"?><Response></Response>'; // replies are sent through the REST API
} else {
    $secret = Crypto::decrypt($channel['app_secret']);
    if (!Meta::verifySignature($raw, $_SERVER['HTTP_X_HUB_SIGNATURE_256'] ?? null, $secret)) {
        Log::warn('webhook_bad_signature', ['channel' => (int)$channel['id']]);
        http_response_code(401); exit('bad signature');
    }
    $payload = json_decode($raw, true);
    $events = is_array($payload) ? Meta::parse($channel, $payload) : [];
    $ackType = 'text/plain'; $ackBody = 'ok';
}

$stored = 0;
if ($channel['status'] === 'active' && Db::val("SELECT status FROM tenants WHERE id=?", [$channel['tenant_id']]) === 'active') {
    foreach ($events as $ev) {
        try { if (Queue::enqueue($channel, $ev)) $stored++; }
        catch (\Throwable $e) { Log::exception($e, 'enqueue_failed', ['channel' => (int)$channel['id']]); http_response_code(500); exit('retry'); } // provider retries
    }
    Db::update('channels', ['last_webhook_at' => now()], 'id=?', [$channel['id']]);
}

// Acknowledge now; providers must see a fast 200.
ignore_user_abort(true);
http_response_code(200);
header('Content-Type: ' . $ackType); header('Connection: close'); header('Content-Length: ' . strlen($ackBody));
echo $ackBody;
if (function_exists('fastcgi_finish_request')) { fastcgi_finish_request(); }
else { while (ob_get_level() > 0) @ob_end_flush(); flush(); }

// Fallback for setups without a worker daemon: process a few events after the response is sent.
if ($stored > 0 && env('QUEUE_INLINE_DRAIN', '1') === '1' && !Queue::workerAlive()) {
    set_time_limit(60);
    try { Queue::drain(3, 40); } catch (\Throwable $e) { Log::exception($e, 'inline_drain_failed'); }
}
